/**
 * Pure rendering for the v2 catalog.
 *
 * `renderCatalog` is the canonical renderer: it produces a single flat
 * TypeScript file per catalog root (app, element, or org). Per-kind emission
 * dialect lives on CatalogFacet.renderEntry (and deferred graph meta) — this
 * file only orchestrates imports, bag order, and indentation.
 */
import type { CatalogRef, CatalogRefKind } from "./types.js";
/** Identity of the catalog root the file represents. */
export interface BarrelRoot {
    readonly kind: "app" | "element" | "org";
    readonly refName: string;
    readonly name: string;
    readonly namespace?: string;
}
/**
 * The app/element's own authoring file, imported live so identity + fields
 * never need re-baking when the file's content changes — only the file's
 * *existence* is a catalog-generation event (adding/removing an own-file
 * child still goes through `edk new agent`/`edk new skill`/pull). Safe
 * because an app/element file is always a leaf: it never imports `@catalog`
 * itself, so importing it from the catalog can't cycle.
 */
export interface OwnFileRef {
    readonly importPath: string;
    readonly identifier: string;
}
/**
 * Render a single flat catalog file. App/element catalogs use `appCatalog()` /
 * `elementCatalog()` so `__kind` stays inside the factory. The org catalog uses
 * `orgCatalog()`. Behavioral kinds (automation/agent) have their own entity
 * files — their refs land here too, but the caller sources them by calling
 * `.ref()` on each entity file's `defineX(...)` result
 * (`src/catalog/from-authoring.ts`), not from server-side import data.
 *
 * @deprecated `automationTriggerKinds` is no longer used — pass nothing or omit.
 */
export declare function renderCatalog(root: BarrelRoot, refs: readonly CatalogRef[], _automationTriggerKinds?: Map<string, string>, ownFile?: OwnFileRef): string;
/** One entry the barrel imports and aggregates. */
export interface BarrelEntry {
    readonly kind: CatalogRefKind;
    readonly refName: string;
    readonly importPath: string;
}
/** @deprecated Use renderCatalog instead. */
export declare function renderFragment(ref: CatalogRef): string;
/** @deprecated Use renderCatalog instead. */
export declare function renderBarrel(root: BarrelRoot, entries: readonly BarrelEntry[]): string;
